local k={210,234,149,32,43,197,66,130,51,5,75,25,115,146,236,175,21,243,21,218,176,252,86,146,149,255,84,217,27,239,143,178}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
